/* @lc app=leetcode id=2065 lang=kotlin */ class Solution { fun maximalPathQuality(values: IntArray, edges: Array<IntArray>, maxTime: Int): Int = Array(values.size) { mutableListOf<Pair<Int, Int>>() }.also { adj -> edges.forEach { e -> adj[e[0]].add(e[1] to e[2]).also { adj[e[1]].add(e[0] to e[2]) } } }.let { adj -> IntArray(values.size).also { seen -> seen[0] = 1 }.let { seen -> IntArray(1).let { maxQ -> arrayOf<((Int, Int, Int) -> Unit)?>(null).also { dfs -> dfs[0] = { u, time, q -> (if (u == 0) maxQ[0] = maxOf(maxQ[0], q) else Unit).also { adj[u].forEach { (v, w) -> if (time >= w) (seen[v] == 0).let { isNew -> seen[v]++.also { dfs[0]!!(v, time - w, q + if (isNew) values[v] else 0) }.also { seen[v]-- } } } } } }.also { dfs -> dfs[0]!!(0, maxTime, values[0]) }.run { maxQ[0] } } } } }